from functools import reduce

class TicTacToe:
    EMPTY = ' '
    PLAYER_X = 'X'
    PLAYER_O = 'O'
    BOARD_SIZE = 3

    def __init__(self, N=3):
        self._board = [[self.EMPTY for _ in range(N)] for _ in range(self.BOARD_SIZE)]
        self._current_player = self.PLAYER_X

    @property
    def current_player(self):
        return self._current_player

    @current_player.setter
    def current_player(self, value):
        self._current_player = value

    def make_move(self, row, col):
        if self._is_cell_empty(row, col):
            self._board[row][col] = self._current_player
            self._switch_player()
            return True
        return False

    def _is_cell_empty(self, row, col):
        return self._board[row][col] == self.EMPTY

    def _switch_player(self):
        self._current_player = self.PLAYER_O if self._current_player == self.PLAYER_X else self.PLAYER_X

    def check_winner(self):
        winner = self._check_rows()
        if winner is not None:
            return winner
        winner = self._check_columns()
        if winner is not None:
            return winner
        winner = self._check_diagonals()
        if winner is not None:
            return winner
        return None

    def _check_rows(self):
        for row in self._board:
            winner = self._get_row_winner(row)
            if winner is not None:
                return winner
        return None

    def _get_row_winner(self, row):
        if all(cell == row[0] for cell in row) and row[0] != self.EMPTY:
            return row[0]
        return None

    def _check_columns(self):
        for col in range(self.BOARD_SIZE):
            column = [self._board[row][col] for row in range(self.BOARD_SIZE)]
            winner = self._get_row_winner(column)
            if winner is not None:
                return winner
        return None

    def _check_diagonals(self):
        main_diag = [self._board[i][i] for i in range(self.BOARD_SIZE)]
        if self._get_row_winner(main_diag) is not None:
            return main_diag[0]
        anti_diag = [self._board[i][self.BOARD_SIZE - 1 - i] for i in range(self.BOARD_SIZE)]
        if self._get_row_winner(anti_diag) is not None:
            return anti_diag[0]
        return None

    def is_board_full(self):
        return not any(self.EMPTY in row for row in self._board)
